from collections import deque, defaultdict
R,C=len(grid),len(grid[0])
def comps(same_color=True):
 seen=set(); out=[]
 for r in range(R):
  for c in range(C):
   if grid[r][c]==8 or (r,c) in seen: continue
   color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     p=(x+dx,y+dy)
     if 0<=p[0]<R and 0<=p[1]<C and p not in seen and grid[p[0]][p[1]]!=8 and (not same_color or grid[p[0]][p[1]]==color):
      seen.add(p);q.append(p)
   out.append((color,cells))
 return out
cc=comps()
def norm(cells):
 mr=min(r for r,c in cells); mc=min(c for r,c in cells)
 return frozenset((r-mr,c-mc) for r,c in cells)
for i,(col,cells) in enumerate(cc):
 rs=[r for r,c in cells];cs=[c for r,c in cells]
 print(i,'color',col,'n',len(cells),'box',(min(rs),min(cs),max(rs),max(cs)),'shape', sorted(norm(cells)))
